function getUsers(string [] groups){ 
  string [] users; 
  for(string group in groups){ 
    string [] currentGrp; 
    currentGrp = addElement(currentGrp, group); 
    for(string user in usersInGroups(currentGrp)){ 
      users = addElementIfNotExist(users, user); 
    } 
  } 
  return users;
} 

