struct _pdField {
    string name;
    string id;
    string alias;
}

function camelCase(string name) {
    string [] words = split(name, " ");
    string cc = toLower(words[0]);

    for(int x=1; x<size(words); x++) {
        string nextWord;
        for(int l=0; l<length(words[x]); l++) {
            if(l==0) {
                nextWord = toUpper(words[x][l]);
            } else {
                nextWord += words[x][l];
            }
        }
        cc += nextWord;
    }
    return cc;
}

